--
-- Table structure for table `query_messages`
--

DROP TABLE IF EXISTS `query_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `query_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `query_id` bigint unsigned NOT NULL,
  `group_id` bigint unsigned NOT NULL,
  `message_id` bigint NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `query_messages_query_id_group_id_message_id_unique` (`query_id`,`group_id`,`message_id`),
  UNIQUE KEY `unique_query_message` (`query_id`,`message_id`),
  KEY `query_messages_group_id_foreign` (`group_id`),
  CONSTRAINT `query_messages_group_id_foreign` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `query_messages_query_id_foreign` FOREIGN KEY (`query_id`) REFERENCES `queries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4093 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
